// v2 — F8: agrega filtros ancho_min_mm/ancho_max_mm al buildFilter.
// Airtable tiene el campo Ancho como string (ej: "60", "320" — en cm).
// El agente pasa los anchos en mm, así que dividimos por 10 y usamos VALUE() para
// que Airtable compare como número.

const args = $input.first().json;
const hasAny = args.query_libre || args.tecnologia || args.linea || args.aplicacion || args.marca || args.zona_cliente || args.ancho_min_mm || args.ancho_max_mm;
if (!hasAny) {
  return [{ json: { status: 'NOT_FOUND', _skip: true, message_to_agent: 'No diste criterios. Pedile al cliente más info: tecnología, aplicación, marca, ancho o presupuesto.' } }];
}

function buildFilter(level) {
  const filters = ['{Status} = "Activo"'];
  if (args.tecnologia) filters.push(`FIND("${args.tecnologia}", ARRAYJOIN({Tecnología}))>0`);
  if (args.linea && level <= 2) filters.push(`{Línea de Producto} = "${args.linea}"`);
  if (args.marca && level <= 2) filters.push(`{Marca} = "${args.marca}"`);
  if (args.aplicacion && level <= 1) filters.push(`FIND("${args.aplicacion}", ARRAYJOIN({Aplicaciones compatibles}))>0`);
  if (args.zona_cliente && level <= 2) filters.push(`FIND("${args.zona_cliente}", ARRAYJOIN({Disponibilidad zona}))>0`);
  // F8: filtros de ancho (Airtable en cm, agente en mm)
  if (args.ancho_min_mm && level <= 2) filters.push(`VALUE({Ancho}) >= ${Number(args.ancho_min_mm) / 10}`);
  if (args.ancho_max_mm && level <= 2) filters.push(`VALUE({Ancho}) <= ${Number(args.ancho_max_mm) / 10}`);
  return `AND(${filters.join(', ')})`;
}

return [{ json: { ...args, _formula: buildFilter(0) } }];

// v2 — F1+F8: filtra records vacíos + prioriza impresoras sobre accesorios.

const matches = $input.all()
  .map(m => m.json)
  .filter(r => r && r.id && r['Modelo']);

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: 'No hay equipos que matcheen esos criterios. Sugerí al cliente ampliar (tecnología/aplicación/marca) o derivá al comercial.',
    trace_id: $execution.id
  } }];
}

function summarize(r) {
  return {
    modelo: r.Modelo,
    marca: r.Marca,
    tecnologia: r['Nombre (from Tecnología)'] || r['Tecnología'] || [],
    linea: r['Línea de Producto'] || '',
    formato: r.Formato || '',
    ancho: r.Ancho || '',
    cabezales_hasta: r['Cabezales hasta'] || null,
    cabezales_tipo: r['Cabezales tipo'] || '',
    datos_extra: r['Datos extra'] || '',
    tipo_de_uso: r['Tipo de Uso'] || '',
    descripcion_corta: r['Descripción corta'] || '',
    disponibilidad_zona: r['Disponibilidad zona'] || []
  };
}

// F8: priorizar impresoras sobre accesorios (planchas/hornos/purificadores)
function isAccesorio(r) {
  const formato = String(r.Formato || '').toLowerCase();
  const modelo = String(r.Modelo || '').toLowerCase();
  return /plancha|horno|purificador|heat\s*press/.test(formato + ' ' + modelo);
}

const impresoras = matches.filter(r => !isAccesorio(r));
const accesorios = matches.filter(r => isAccesorio(r));
const ordered = [...impresoras, ...accesorios];

const principal = summarize(ordered[0]);
const alternativas = ordered.slice(1, 3).map(summarize);

let status, msg;
if (ordered.length === 1) {
  status = 'RESOLVED';
  msg = `1 equipo encontrado: ${principal.modelo} (${principal.marca}).`;
} else if (ordered.length <= 3) {
  status = 'RESOLVED';
  msg = `Equipo principal: ${principal.modelo}. Alternativas: ${alternativas.map(a => a.modelo).join(', ')}.`;
} else {
  status = 'AMBIGUOUS';
  msg = `Hay ${ordered.length} equipos. Te presento el más relevante (${principal.modelo}) y 2 alternativas. Si el cliente necesita más opciones, pedile criterios adicionales.`;
}

return [{ json: {
  status,
  data: {
    equipo_principal: principal,
    alternativas,
    total_matches: ordered.length
  },
  message_to_agent: msg,
  trace_id: $execution.id
} }];
